import fs from "node:fs/promises";
import path from "node:path";
import { ErrorCodes, errorShape } from "../protocol/index.js";
import type { GatewayRequestHandlers } from "./types.js";
import { resolveUserPath } from "../../utils.js";
import { loadAuthProfileStore, saveAuthProfileStore } from "../../agents/auth-profiles.js";
import type { AuthProfileStore } from "../../agents/auth-profiles/types.js";
import { isSecretRef } from "../../config/types.secrets.js";

// ─── Constants ───────────────────────────────────────────────────────────────

const DEFAULT_SECRETS_PATH = "~/.openclaw/secrets.json";

// ─── Helpers ─────────────────────────────────────────────────────────────────

function getSecretsFilePath(): string {
  return resolveUserPath(DEFAULT_SECRETS_PATH);
}

async function readSecretsFile(): Promise<Record<string, string>> {
  const filePath = getSecretsFilePath();
  try {
    const raw = await fs.readFile(filePath, "utf-8");
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return {};
    }
    return parsed as Record<string, string>;
  } catch {
    return {};
  }
}

async function writeSecretsFile(secrets: Record<string, string>): Promise<void> {
  const filePath = getSecretsFilePath();
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, JSON.stringify(secrets, null, 2) + "\n", { mode: 0o600 });
}

function maskSecret(value: string): string {
  if (!value || value.length <= 8) return "••••••••";
  return `${value.slice(0, 4)}...${value.slice(-4)}`;
}

async function fileExists(filePath: string): Promise<boolean> {
  try {
    await fs.access(filePath);
    return true;
  } catch {
    return false;
  }
}

// ─── Config helpers ──────────────────────────────────────────────────────────

/**
 * Read openclaw.json, apply a mutation, and write it back.
 */
async function patchConfig(
  mutate: (config: Record<string, unknown>) => void,
): Promise<void> {
  const configPath = resolveUserPath("~/.openclaw/openclaw.json");
  const raw = await fs.readFile(configPath, "utf-8");
  const config = JSON.parse(raw) as Record<string, unknown>;
  mutate(config);
  await fs.writeFile(configPath, JSON.stringify(config, null, 2) + "\n");
}

function ensureSecretsProvider(config: Record<string, unknown>): void {
  if (!config.secrets || typeof config.secrets !== "object") {
    config.secrets = {};
  }
  const secrets = config.secrets as Record<string, unknown>;
  if (!secrets.providers || typeof secrets.providers !== "object") {
    secrets.providers = {};
  }
  const providers = secrets.providers as Record<string, unknown>;
  if (!providers.default) {
    providers.default = {
      source: "file",
      path: DEFAULT_SECRETS_PATH,
      mode: "json",
    };
  }
  if (!secrets.defaults || typeof secrets.defaults !== "object") {
    secrets.defaults = {};
  }
  const defaults = secrets.defaults as Record<string, unknown>;
  if (!defaults.file) {
    defaults.file = "default";
  }
}

function makeSecretRef(secretId: string): { source: string; provider: string; id: string } {
  return { source: "file", provider: "default", id: `/${secretId}` };
}

// ─── Key pattern detection ───────────────────────────────────────────────────

const KEY_PATTERNS = [
  /apiKey$/i, /api_key$/i, /^token$/i, /secret$/i,
  /_KEY$/, /_TOKEN$/, /_SECRET$/,
];

const SKIP_PATHS = [
  "meta", "wizard", "update", "browser", "auth.profiles",
  "gateway.auth.token", "channels.telegram.botToken", "channels.discord.token",
];

function isKeyField(name: string): boolean {
  return KEY_PATTERNS.some(p => p.test(name));
}

function shouldSkipPath(pathStr: string): boolean {
  return SKIP_PATHS.some(s => pathStr.startsWith(s));
}

interface PlaintextKey {
  path: string[];
  pathStr: string;
  value: string;
}

function scanPlaintextKeys(
  obj: Record<string, unknown>,
  currentPath: string[] = [],
  results: PlaintextKey[] = [],
): PlaintextKey[] {
  if (!obj || typeof obj !== "object") return results;
  for (const [key, value] of Object.entries(obj)) {
    const p = [...currentPath, key];
    const pathStr = p.join(".");
    if (shouldSkipPath(pathStr)) continue;
    if (isKeyField(key) && typeof value === "string" && value.length > 0) {
      results.push({ path: p, pathStr, value });
    }
    if (value && typeof value === "object" && !Array.isArray(value)) {
      scanPlaintextKeys(value as Record<string, unknown>, p, results);
    }
  }
  return results;
}

function isSecretRef(value: unknown): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const v = value as Record<string, unknown>;
  return (v.source === "env" || v.source === "file" || v.source === "exec") &&
    typeof v.provider === "string" && typeof v.id === "string";
}

// ─── RPC Handlers ────────────────────────────────────────────────────────────

export function createSecretsHandlers(params: {
  reloadSecrets: () => Promise<{ warningCount: number }>;
}): GatewayRequestHandlers {
  return {
    "secrets.reload": async ({ respond }) => {
      try {
        const result = await params.reloadSecrets();
        respond(true, { ok: true, warningCount: result.warningCount });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.status": async ({ respond }) => {
      try {
        const filePath = getSecretsFilePath();
        const exists = await fileExists(filePath);
        const secrets = exists ? await readSecretsFile() : {};
        const keyCount = Object.keys(secrets).length;

        // Check if config has secrets provider configured
        const configPath = resolveUserPath("~/.openclaw/openclaw.json");
        let providerConfigured = false;
        try {
          const raw = await fs.readFile(configPath, "utf-8");
          const config = JSON.parse(raw) as Record<string, unknown>;
          const sec = config.secrets as Record<string, unknown> | undefined;
          const providers = sec?.providers as Record<string, unknown> | undefined;
          providerConfigured = !!providers?.default;
        } catch { /* */ }

        // Count plaintext keys in config
        let plaintextCount = 0;
        try {
          const raw = await fs.readFile(configPath, "utf-8");
          const config = JSON.parse(raw) as Record<string, unknown>;
          plaintextCount = scanPlaintextKeys(config).length;
        } catch { /* */ }

        respond(true, {
          ok: true,
          vaultExists: exists,
          vaultPath: filePath,
          keyCount,
          providerConfigured,
          plaintextCount,
        });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.list": async ({ respond }) => {
      try {
        const secrets = await readSecretsFile();
        const keys = Object.entries(secrets).map(([id, value]) => ({
          id,
          masked: maskSecret(typeof value === "string" ? value : ""),
        }));
        respond(true, { ok: true, keys });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.write": async ({ params: p, respond }) => {
      try {
        const id = (p as { id?: string })?.id?.trim();
        const value = (p as { value?: string })?.value?.trim();
        const envEntry = (p as { envEntry?: boolean })?.envEntry !== false; // default true
        if (!id || !value) {
          respond(false, undefined, errorShape(ErrorCodes.INVALID_REQUEST, "id and value required"));
          return;
        }

        // 1. Write to secrets file
        const secrets = await readSecretsFile();
        secrets[id] = value;
        await writeSecretsFile(secrets);

        // 2. Update config: ensure provider + optionally add env entry
        let configChanged = false;
        await patchConfig((config) => {
          ensureSecretsProvider(config);

          if (envEntry) {
            const env = config.env as Record<string, unknown> | undefined;
            if (env && id in env) {
              env[id] = makeSecretRef(id);
            } else if (env) {
              env[id] = makeSecretRef(id);
            } else {
              config.env = { [id]: makeSecretRef(id) };
            }
            configChanged = true;
          }
        });

        // Don't auto-reload — let the UI prompt the user to restart
        // so we don't crash mid-session
        respond(true, { ok: true, id, masked: maskSecret(value), restartNeeded: true, configChanged });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.delete": async ({ params: p, respond }) => {
      try {
        const id = (p as { id?: string })?.id?.trim();
        if (!id) {
          respond(false, undefined, errorShape(ErrorCodes.INVALID_REQUEST, "id required"));
          return;
        }

        // 1. Remove from secrets file
        const secrets = await readSecretsFile();
        delete secrets[id];
        await writeSecretsFile(secrets);

        // 2. Remove/null the config ref
        await patchConfig((config) => {
          const env = config.env as Record<string, unknown> | undefined;
          if (env && id in env) {
            delete env[id];
          }
        });

        // 3. Reload
        try {
          await params.reloadSecrets();
        } catch { /* non-fatal */ }

        respond(true, { ok: true, id });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.migrate": async ({ respond }) => {
      try {
        const configPath = resolveUserPath("~/.openclaw/openclaw.json");
        const raw = await fs.readFile(configPath, "utf-8");
        const config = JSON.parse(raw) as Record<string, unknown>;

        // Find all plaintext keys in env block
        const env = config.env as Record<string, unknown> | undefined;
        if (!env) {
          respond(true, { ok: true, migrated: 0, keys: [] });
          return;
        }

        const migratedKeys: string[] = [];
        const secrets = await readSecretsFile();

        for (const [key, value] of Object.entries(env)) {
          // Skip if already a SecretRef
          if (isSecretRef(value)) continue;
          // Skip if not a string
          if (typeof value !== "string" || !value.trim()) continue;
          // Only migrate things that look like API keys
          if (!isKeyField(key)) continue;

          // Move to secrets file
          secrets[key] = value;
          // Replace with ref in config
          env[key] = makeSecretRef(key);
          migratedKeys.push(key);
        }

        if (migratedKeys.length === 0) {
          respond(true, { ok: true, migrated: 0, keys: [] });
          return;
        }

        // Write secrets file
        await writeSecretsFile(secrets);

        // Ensure provider in config and write back
        ensureSecretsProvider(config);
        await fs.writeFile(configPath, JSON.stringify(config, null, 2) + "\n");

        // Reload
        try {
          await params.reloadSecrets();
        } catch { /* non-fatal */ }

        respond(true, { ok: true, migrated: migratedKeys.length, keys: migratedKeys });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.authProfiles.list": async ({ respond }) => {
      try {
        const agentDir = resolveUserPath("~/.openclaw/agents/main/agent");
        const store = loadAuthProfileStore(agentDir) as AuthProfileStore;
        const profiles = Object.entries(store.profiles ?? {}).map(([id, cred]) => {
          const stats = store.usageStats?.[id];
          const lastGoodProvider = Object.entries(store.lastGood ?? {}).find(
            ([, v]) => v === id,
          )?.[0];

          let status: "active" | "error" | "cooldown" | "unused" = "unused";
          if (stats?.cooldownUntil && stats.cooldownUntil > Date.now()) {
            status = "cooldown";
          } else if (stats?.errorCount && stats.errorCount > 0) {
            status = "error";
          } else if (stats?.lastUsed && stats.lastUsed > 0) {
            status = "active";
          }

          const inVault =
            ("keyRef" in cred && isSecretRef(cred.keyRef)) ||
            ("tokenRef" in cred && isSecretRef((cred as any).tokenRef));

          return {
            id,
            type: cred.type,
            provider: cred.provider,
            email: (cred as any).email ?? null,
            inVault,
            hasCredential:
              inVault ||
              !!("key" in cred && (cred as any).key) ||
              !!("token" in cred && (cred as any).token),
            status,
            isLastGood: !!lastGoodProvider,
            lastUsed: stats?.lastUsed ?? null,
            errorCount: stats?.errorCount ?? 0,
            lastFailureAt: stats?.lastFailureAt ?? null,
            cooldownUntil: stats?.cooldownUntil ?? null,
          };
        });

        respond(true, { ok: true, profiles });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.authProfiles.resetErrors": async ({ params: p, respond }) => {
      try {
        const profileId = (p as { profileId?: string })?.profileId?.trim();
        if (!profileId) {
          respond(false, undefined, errorShape(ErrorCodes.INVALID_REQUEST, "profileId required"));
          return;
        }
        const agentDir = resolveUserPath("~/.openclaw/agents/main/agent");
        const store = loadAuthProfileStore(agentDir) as AuthProfileStore;
        if (store.usageStats?.[profileId]) {
          store.usageStats[profileId].errorCount = 0;
          store.usageStats[profileId].lastFailureAt = undefined;
          store.usageStats[profileId].cooldownUntil = undefined;
          store.usageStats[profileId].disabledUntil = undefined;
          store.usageStats[profileId].disabledReason = undefined;
          saveAuthProfileStore(agentDir, store);
        }
        respond(true, { ok: true, profileId });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },

    "secrets.authProfiles.delete": async ({ params: p, respond }) => {
      try {
        const profileId = (p as { profileId?: string })?.profileId?.trim();
        if (!profileId) {
          respond(false, undefined, errorShape(ErrorCodes.INVALID_REQUEST, "profileId required"));
          return;
        }
        const agentDir = resolveUserPath("~/.openclaw/agents/main/agent");
        const store = loadAuthProfileStore(agentDir) as AuthProfileStore;
        delete store.profiles[profileId];
        if (store.usageStats) delete store.usageStats[profileId];
        // Clean from order arrays
        if (store.order) {
          for (const [provider, ids] of Object.entries(store.order)) {
            store.order[provider] = ids.filter((id: string) => id !== profileId);
          }
        }
        // Clean from lastGood
        if (store.lastGood) {
          for (const [provider, id] of Object.entries(store.lastGood)) {
            if (id === profileId) delete store.lastGood[provider];
          }
        }
        saveAuthProfileStore(agentDir, store);
        respond(true, { ok: true, profileId });
      } catch (err) {
        respond(false, undefined, errorShape(ErrorCodes.UNAVAILABLE, String(err)));
      }
    },
  };
}

import type { GatewayBrowserClient } from "../gateway.ts";
import type { SkillStatusReport } from "../types.ts";

export type VaultKeyEntry = {
  id: string;
  masked: string;
};

export type SkillsState = {
  client: GatewayBrowserClient | null;
  connected: boolean;
  skillsLoading: boolean;
  skillsReport: SkillStatusReport | null;
  skillsError: string | null;
  skillsBusyKey: string | null;
  skillEdits: Record<string, string>;
  skillMessages: SkillMessageMap;
  vaultKeys: VaultKeyEntry[];
  vaultKeysLoading: boolean;
};

export type SkillMessage = {
  kind: "success" | "error";
  message: string;
};

export type SkillMessageMap = Record<string, SkillMessage>;

type LoadSkillsOptions = {
  clearMessages?: boolean;
};

function setSkillMessage(state: SkillsState, key: string, message?: SkillMessage) {
  if (!key.trim()) {
    return;
  }
  const next = { ...state.skillMessages };
  if (message) {
    next[key] = message;
  } else {
    delete next[key];
  }
  state.skillMessages = next;
}

function getErrorMessage(err: unknown) {
  if (err instanceof Error) {
    return err.message;
  }
  return String(err);
}

export async function loadSkills(state: SkillsState, options?: LoadSkillsOptions) {
  if (options?.clearMessages && Object.keys(state.skillMessages).length > 0) {
    state.skillMessages = {};
  }
  if (!state.client || !state.connected) {
    return;
  }
  if (state.skillsLoading) {
    return;
  }
  state.skillsLoading = true;
  state.skillsError = null;
  try {
    const res = await state.client.request<SkillStatusReport | undefined>("skills.status", {});
    if (res) {
      state.skillsReport = res;
    }
  } catch (err) {
    state.skillsError = getErrorMessage(err);
  } finally {
    state.skillsLoading = false;
  }
}

export function updateSkillEdit(state: SkillsState, skillKey: string, value: string) {
  state.skillEdits = { ...state.skillEdits, [skillKey]: value };
}

export async function updateSkillEnabled(state: SkillsState, skillKey: string, enabled: boolean) {
  if (!state.client || !state.connected) {
    return;
  }
  state.skillsBusyKey = skillKey;
  state.skillsError = null;
  try {
    await state.client.request("skills.update", { skillKey, enabled });
    await loadSkills(state);
    setSkillMessage(state, skillKey, {
      kind: "success",
      message: enabled ? "Skill enabled" : "Skill disabled",
    });
  } catch (err) {
    const message = getErrorMessage(err);
    state.skillsError = message;
    setSkillMessage(state, skillKey, {
      kind: "error",
      message,
    });
  } finally {
    state.skillsBusyKey = null;
  }
}

export async function saveSkillApiKey(state: SkillsState, skillKey: string) {
  if (!state.client || !state.connected) {
    return;
  }
  state.skillsBusyKey = skillKey;
  state.skillsError = null;
  try {
    const apiKey = state.skillEdits[skillKey] ?? "";
    await state.client.request("skills.update", { skillKey, apiKey });
    await loadSkills(state);
    setSkillMessage(state, skillKey, {
      kind: "success",
      message: "API key saved",
    });
  } catch (err) {
    const message = getErrorMessage(err);
    state.skillsError = message;
    setSkillMessage(state, skillKey, {
      kind: "error",
      message,
    });
  } finally {
    state.skillsBusyKey = null;
  }
}

export async function installSkill(
  state: SkillsState,
  skillKey: string,
  name: string,
  installId: string,
) {
  if (!state.client || !state.connected) {
    return;
  }
  state.skillsBusyKey = skillKey;
  state.skillsError = null;
  try {
    const result = await state.client.request<{ message?: string }>("skills.install", {
      name,
      installId,
      timeoutMs: 120000,
    });
    await loadSkills(state);
    setSkillMessage(state, skillKey, {
      kind: "success",
      message: result?.message ?? "Installed",
    });
  } catch (err) {
    const message = getErrorMessage(err);
    state.skillsError = message;
    setSkillMessage(state, skillKey, {
      kind: "error",
      message,
    });
  } finally {
    state.skillsBusyKey = null;
  }
}

export async function loadVaultKeys(state: SkillsState) {
  if (!state.client || !state.connected) return;
  state.vaultKeysLoading = true;
  try {
    const res = await state.client.request<{ keys: VaultKeyEntry[] }>("secrets.list", {});
    state.vaultKeys = res?.keys ?? [];
  } catch {
    state.vaultKeys = [];
  } finally {
    state.vaultKeysLoading = false;
  }
}

export async function linkSkillToVaultKey(state: SkillsState, skillKey: string, vaultKeyId: string) {
  if (!state.client || !state.connected) return;
  state.skillsBusyKey = skillKey;
  try {
    await state.client.request("skills.update", { skillKey, vaultKeyId });
    await loadSkills(state);
    setSkillMessage(state, skillKey, {
      kind: "success",
      message: vaultKeyId ? "Linked to vault key: " + vaultKeyId : "Unlinked from vault key",
    });
  } catch (err) {
    setSkillMessage(state, skillKey, { kind: "error", message: getErrorMessage(err) });
  } finally {
    state.skillsBusyKey = null;
  }
}

export async function addVaultKeyAndLink(
  state: SkillsState,
  skillKey: string,
  keyName: string,
  keyValue: string,
) {
  if (!state.client || !state.connected) return;
  state.skillsBusyKey = skillKey;
  try {
    await state.client.request("secrets.write", {
      id: keyName.trim(),
      value: keyValue.trim(),
      envEntry: false,
    });
    await state.client.request("skills.update", { skillKey, vaultKeyId: keyName.trim() });
    await loadSkills(state);
    await loadVaultKeys(state);
    setSkillMessage(state, skillKey, {
      kind: "success",
      message: "Created and linked vault key: " + keyName,
    });
  } catch (err) {
    setSkillMessage(state, skillKey, { kind: "error", message: getErrorMessage(err) });
  } finally {
    state.skillsBusyKey = null;
  }
}

import {
  listAgentIds,
  resolveAgentWorkspaceDir,
  resolveDefaultAgentId,
} from "../../agents/agent-scope.js";
import { installSkill } from "../../agents/skills-install.js";
import { buildWorkspaceSkillStatus } from "../../agents/skills-status.js";
import { loadWorkspaceSkillEntries, type SkillEntry } from "../../agents/skills.js";
import { listAgentWorkspaceDirs } from "../../agents/workspace-dirs.js";
import type { OpenClawConfig } from "../../config/config.js";
import { loadConfig, writeConfigFile } from "../../config/config.js";
import { getRemoteSkillEligibility } from "../../infra/skills-remote.js";
import { normalizeAgentId } from "../../routing/session-key.js";
import { normalizeSecretInput } from "../../utils/normalize-secret-input.js";
import {
  ErrorCodes,
  errorShape,
  formatValidationErrors,
  validateSkillsBinsParams,
  validateSkillsInstallParams,
  validateSkillsStatusParams,
  validateSkillsUpdateParams,
} from "../protocol/index.js";
import type { GatewayRequestHandlers } from "./types.js";

function collectSkillBins(entries: SkillEntry[]): string[] {
  const bins = new Set<string>();
  for (const entry of entries) {
    const required = entry.metadata?.requires?.bins ?? [];
    const anyBins = entry.metadata?.requires?.anyBins ?? [];
    const install = entry.metadata?.install ?? [];
    for (const bin of required) {
      const trimmed = bin.trim();
      if (trimmed) {
        bins.add(trimmed);
      }
    }
    for (const bin of anyBins) {
      const trimmed = bin.trim();
      if (trimmed) {
        bins.add(trimmed);
      }
    }
    for (const spec of install) {
      const specBins = spec?.bins ?? [];
      for (const bin of specBins) {
        const trimmed = String(bin).trim();
        if (trimmed) {
          bins.add(trimmed);
        }
      }
    }
  }
  return [...bins].toSorted();
}

export const skillsHandlers: GatewayRequestHandlers = {
  "skills.status": ({ params, respond }) => {
    if (!validateSkillsStatusParams(params)) {
      respond(
        false,
        undefined,
        errorShape(
          ErrorCodes.INVALID_REQUEST,
          `invalid skills.status params: ${formatValidationErrors(validateSkillsStatusParams.errors)}`,
        ),
      );
      return;
    }
    const cfg = loadConfig();
    const agentIdRaw = typeof params?.agentId === "string" ? params.agentId.trim() : "";
    const agentId = agentIdRaw ? normalizeAgentId(agentIdRaw) : resolveDefaultAgentId(cfg);
    if (agentIdRaw) {
      const knownAgents = listAgentIds(cfg);
      if (!knownAgents.includes(agentId)) {
        respond(
          false,
          undefined,
          errorShape(ErrorCodes.INVALID_REQUEST, `unknown agent id "${agentIdRaw}"`),
        );
        return;
      }
    }
    const workspaceDir = resolveAgentWorkspaceDir(cfg, agentId);
    const report = buildWorkspaceSkillStatus(workspaceDir, {
      config: cfg,
      eligibility: { remote: getRemoteSkillEligibility() },
    });
    respond(true, report, undefined);
  },
  "skills.bins": ({ params, respond }) => {
    if (!validateSkillsBinsParams(params)) {
      respond(
        false,
        undefined,
        errorShape(
          ErrorCodes.INVALID_REQUEST,
          `invalid skills.bins params: ${formatValidationErrors(validateSkillsBinsParams.errors)}`,
        ),
      );
      return;
    }
    const cfg = loadConfig();
    const workspaceDirs = listAgentWorkspaceDirs(cfg);
    const bins = new Set<string>();
    for (const workspaceDir of workspaceDirs) {
      const entries = loadWorkspaceSkillEntries(workspaceDir, { config: cfg });
      for (const bin of collectSkillBins(entries)) {
        bins.add(bin);
      }
    }
    respond(true, { bins: [...bins].toSorted() }, undefined);
  },
  "skills.install": async ({ params, respond }) => {
    if (!validateSkillsInstallParams(params)) {
      respond(
        false,
        undefined,
        errorShape(
          ErrorCodes.INVALID_REQUEST,
          `invalid skills.install params: ${formatValidationErrors(validateSkillsInstallParams.errors)}`,
        ),
      );
      return;
    }
    const p = params as {
      name: string;
      installId: string;
      timeoutMs?: number;
    };
    const cfg = loadConfig();
    const workspaceDirRaw = resolveAgentWorkspaceDir(cfg, resolveDefaultAgentId(cfg));
    const result = await installSkill({
      workspaceDir: workspaceDirRaw,
      skillName: p.name,
      installId: p.installId,
      timeoutMs: p.timeoutMs,
      config: cfg,
    });
    respond(
      result.ok,
      result,
      result.ok ? undefined : errorShape(ErrorCodes.UNAVAILABLE, result.message),
    );
  },
  "skills.update": async ({ params, respond }) => {
    if (!validateSkillsUpdateParams(params)) {
      respond(
        false,
        undefined,
        errorShape(
          ErrorCodes.INVALID_REQUEST,
          `invalid skills.update params: ${formatValidationErrors(validateSkillsUpdateParams.errors)}`,
        ),
      );
      return;
    }
    const p = params as {
      skillKey: string;
      enabled?: boolean;
      apiKey?: string;
      vaultKeyId?: string;
      env?: Record<string, string>;
    };
    const cfg = loadConfig();
    const skills = cfg.skills ? { ...cfg.skills } : {};
    const entries = skills.entries ? { ...skills.entries } : {};
    const current = entries[p.skillKey] ? { ...entries[p.skillKey] } : {};
    if (typeof p.enabled === "boolean") {
      current.enabled = p.enabled;
    }
    if (typeof p.vaultKeyId === "string" && p.vaultKeyId.trim()) {
      // Link to a vault key via SecretRef
      const keyId = p.vaultKeyId.trim();
      current.apiKey = { source: "file", provider: "default", id: `/${keyId}` } as unknown as string;
    } else if (p.vaultKeyId === "") {
      // Unlink — clear the apiKey
      delete current.apiKey;
    } else if (typeof p.apiKey === "string") {
      const trimmed = normalizeSecretInput(p.apiKey);
      if (trimmed) {
        current.apiKey = trimmed;
      } else {
        delete current.apiKey;
      }
    }
    if (p.env && typeof p.env === "object") {
      const nextEnv = current.env ? { ...current.env } : {};
      for (const [key, value] of Object.entries(p.env)) {
        const trimmedKey = key.trim();
        if (!trimmedKey) {
          continue;
        }
        const trimmedVal = value.trim();
        if (!trimmedVal) {
          delete nextEnv[trimmedKey];
        } else {
          nextEnv[trimmedKey] = trimmedVal;
        }
      }
      current.env = nextEnv;
    }
    entries[p.skillKey] = current;
    skills.entries = entries;
    const nextConfig: OpenClawConfig = {
      ...cfg,
      skills,
    };
    await writeConfigFile(nextConfig);
    respond(true, { ok: true, skillKey: p.skillKey, config: current }, undefined);
  },
};

import fs from "node:fs";
import path from "node:path";

function extractVaultKeyId(apiKey: unknown): string | undefined {
  if (apiKey && typeof apiKey === "object" && "source" in apiKey && "id" in apiKey) {
    const ref = apiKey as { source: string; id: string };
    if (ref.source === "file" && ref.id) {
      return ref.id.startsWith("/") ? ref.id.slice(1) : ref.id;
    }
  }
  return undefined;
}

let _rawConfigCache: Record<string, unknown> | null = null;
let _rawConfigMtime = 0;

function extractVaultKeyIdFromConfig(skillKey: string): string | undefined {
  // Read the raw JSON to get the unresolved SecretRef (runtime resolves them to strings)
  const configPath = path.join(CONFIG_DIR, "openclaw.json");
  try {
    const stat = fs.statSync(configPath);
    if (!_rawConfigCache || stat.mtimeMs !== _rawConfigMtime) {
      _rawConfigCache = JSON.parse(fs.readFileSync(configPath, "utf8")) as Record<string, unknown>;
      _rawConfigMtime = stat.mtimeMs;
    }
    const skills = (_rawConfigCache?.skills as Record<string, unknown>)?.entries as Record<string, Record<string, unknown>> | undefined;
    const entry = skills?.[skillKey];
    return extractVaultKeyId(entry?.apiKey);
  } catch {
    return undefined;
  }
}
import type { OpenClawConfig } from "../config/config.js";
import { evaluateEntryRequirementsForCurrentPlatform } from "../shared/entry-status.js";
import type { RequirementConfigCheck, Requirements } from "../shared/requirements.js";
import { CONFIG_DIR } from "../utils.js";
import {
  hasBinary,
  isBundledSkillAllowed,
  isConfigPathTruthy,
  loadWorkspaceSkillEntries,
  resolveBundledAllowlist,
  resolveSkillConfig,
  resolveSkillsInstallPreferences,
  type SkillEntry,
  type SkillEligibilityContext,
  type SkillInstallSpec,
  type SkillsInstallPreferences,
} from "./skills.js";
import { resolveBundledSkillsContext } from "./skills/bundled-context.js";

export type SkillStatusConfigCheck = RequirementConfigCheck;

export type SkillInstallOption = {
  id: string;
  kind: SkillInstallSpec["kind"];
  label: string;
  bins: string[];
};

export type SkillStatusEntry = {
  name: string;
  description: string;
  source: string;
  bundled: boolean;
  filePath: string;
  baseDir: string;
  skillKey: string;
  primaryEnv?: string;
  vaultKeyId?: string;
  emoji?: string;
  homepage?: string;
  always: boolean;
  disabled: boolean;
  blockedByAllowlist: boolean;
  eligible: boolean;
  requirements: Requirements;
  missing: Requirements;
  configChecks: SkillStatusConfigCheck[];
  install: SkillInstallOption[];
};

export type SkillStatusReport = {
  workspaceDir: string;
  managedSkillsDir: string;
  skills: SkillStatusEntry[];
};

function resolveSkillKey(entry: SkillEntry): string {
  return entry.metadata?.skillKey ?? entry.skill.name;
}

function selectPreferredInstallSpec(
  install: SkillInstallSpec[],
  prefs: SkillsInstallPreferences,
): { spec: SkillInstallSpec; index: number } | undefined {
  if (install.length === 0) {
    return undefined;
  }

  const indexed = install.map((spec, index) => ({ spec, index }));
  const findKind = (kind: SkillInstallSpec["kind"]) =>
    indexed.find((item) => item.spec.kind === kind);

  const brewSpec = findKind("brew");
  const nodeSpec = findKind("node");
  const goSpec = findKind("go");
  const uvSpec = findKind("uv");
  const downloadSpec = findKind("download");
  const brewAvailable = hasBinary("brew");

  // Table-driven preference chain; first match wins.
  const pickers: Array<() => { spec: SkillInstallSpec; index: number } | undefined> = [
    () => (prefs.preferBrew && brewAvailable ? brewSpec : undefined),
    () => uvSpec,
    () => nodeSpec,
    // Only prefer brew when available to avoid guaranteed failure on Linux/Docker.
    () => (brewAvailable ? brewSpec : undefined),
    () => goSpec,
    // Prefer download over an unavailable brew spec.
    () => downloadSpec,
    // Last resort: surface descriptive brew-missing error instead of "no installer found".
    () => brewSpec,
    () => indexed[0],
  ];

  for (const pick of pickers) {
    const selected = pick();
    if (selected) {
      return selected;
    }
  }

  return undefined;
}

function normalizeInstallOptions(
  entry: SkillEntry,
  prefs: SkillsInstallPreferences,
): SkillInstallOption[] {
  // If the skill is explicitly OS-scoped, don't surface install actions on unsupported platforms.
  // (Installers run locally; remote OS eligibility is handled separately.)
  const requiredOs = entry.metadata?.os ?? [];
  if (requiredOs.length > 0 && !requiredOs.includes(process.platform)) {
    return [];
  }

  const install = entry.metadata?.install ?? [];
  if (install.length === 0) {
    return [];
  }

  const platform = process.platform;
  const filtered = install.filter((spec) => {
    const osList = spec.os ?? [];
    return osList.length === 0 || osList.includes(platform);
  });
  if (filtered.length === 0) {
    return [];
  }

  const toOption = (spec: SkillInstallSpec, index: number): SkillInstallOption => {
    const id = (spec.id ?? `${spec.kind}-${index}`).trim();
    const bins = spec.bins ?? [];
    let label = (spec.label ?? "").trim();
    if (spec.kind === "node" && spec.package) {
      label = `Install ${spec.package} (${prefs.nodeManager})`;
    }
    if (!label) {
      if (spec.kind === "brew" && spec.formula) {
        label = `Install ${spec.formula} (brew)`;
      } else if (spec.kind === "node" && spec.package) {
        label = `Install ${spec.package} (${prefs.nodeManager})`;
      } else if (spec.kind === "go" && spec.module) {
        label = `Install ${spec.module} (go)`;
      } else if (spec.kind === "uv" && spec.package) {
        label = `Install ${spec.package} (uv)`;
      } else if (spec.kind === "download" && spec.url) {
        const url = spec.url.trim();
        const last = url.split("/").pop();
        label = `Download ${last && last.length > 0 ? last : url}`;
      } else {
        label = "Run installer";
      }
    }
    return { id, kind: spec.kind, label, bins };
  };

  const allDownloads = filtered.every((spec) => spec.kind === "download");
  if (allDownloads) {
    return filtered.map((spec, index) => toOption(spec, index));
  }

  const preferred = selectPreferredInstallSpec(filtered, prefs);
  if (!preferred) {
    return [];
  }
  return [toOption(preferred.spec, preferred.index)];
}

function buildSkillStatus(
  entry: SkillEntry,
  config?: OpenClawConfig,
  prefs?: SkillsInstallPreferences,
  eligibility?: SkillEligibilityContext,
  bundledNames?: Set<string>,
): SkillStatusEntry {
  const skillKey = resolveSkillKey(entry);
  const skillConfig = resolveSkillConfig(config, skillKey);
  const disabled = skillConfig?.enabled === false;
  const allowBundled = resolveBundledAllowlist(config);
  const blockedByAllowlist = !isBundledSkillAllowed(entry, allowBundled);
  const always = entry.metadata?.always === true;
  const isEnvSatisfied = (envName: string) =>
    Boolean(
      process.env[envName] ||
      skillConfig?.env?.[envName] ||
      (skillConfig?.apiKey && entry.metadata?.primaryEnv === envName),
    );
  const isConfigSatisfied = (pathStr: string) => isConfigPathTruthy(config, pathStr);
  const bundled =
    bundledNames && bundledNames.size > 0
      ? bundledNames.has(entry.skill.name)
      : entry.skill.source === "openclaw-bundled";

  const { emoji, homepage, required, missing, requirementsSatisfied, configChecks } =
    evaluateEntryRequirementsForCurrentPlatform({
      always,
      entry,
      hasLocalBin: hasBinary,
      remote: eligibility?.remote,
      isEnvSatisfied,
      isConfigSatisfied,
    });
  const eligible = !disabled && !blockedByAllowlist && requirementsSatisfied;

  return {
    name: entry.skill.name,
    description: entry.skill.description,
    source: entry.skill.source,
    bundled,
    filePath: entry.skill.filePath,
    baseDir: entry.skill.baseDir,
    skillKey,
    primaryEnv: entry.metadata?.primaryEnv,
    vaultKeyId: extractVaultKeyIdFromConfig(skillKey),
    emoji,
    homepage,
    always,
    disabled,
    blockedByAllowlist,
    eligible,
    requirements: required,
    missing,
    configChecks,
    install: normalizeInstallOptions(entry, prefs ?? resolveSkillsInstallPreferences(config)),
  };
}

export function buildWorkspaceSkillStatus(
  workspaceDir: string,
  opts?: {
    config?: OpenClawConfig;
    managedSkillsDir?: string;
    entries?: SkillEntry[];
    eligibility?: SkillEligibilityContext;
  },
): SkillStatusReport {
  const managedSkillsDir = opts?.managedSkillsDir ?? path.join(CONFIG_DIR, "skills");
  const bundledContext = resolveBundledSkillsContext();
  const skillEntries =
    opts?.entries ??
    loadWorkspaceSkillEntries(workspaceDir, {
      config: opts?.config,
      managedSkillsDir,
      bundledSkillsDir: bundledContext.dir,
    });
  const prefs = resolveSkillsInstallPreferences(opts?.config);
  return {
    workspaceDir,
    managedSkillsDir,
    skills: skillEntries.map((entry) =>
      buildSkillStatus(entry, opts?.config, prefs, opts?.eligibility, bundledContext.names),
    ),
  };
}

import { html, nothing } from "lit";
import type { SkillMessageMap, VaultKeyEntry } from "../controllers/skills.ts";
import { clampText } from "../format.ts";
import type { SkillStatusEntry, SkillStatusReport } from "../types.ts";
import { groupSkills } from "./skills-grouping.ts";
import {
  computeSkillMissing,
  computeSkillReasons,
  renderSkillStatusChips,
} from "./skills-shared.ts";

export type SkillsProps = {
  loading: boolean;
  report: SkillStatusReport | null;
  error: string | null;
  filter: string;
  edits: Record<string, string>;
  busyKey: string | null;
  messages: SkillMessageMap;
  vaultKeys: VaultKeyEntry[];
  skillAddingKey: Record<string, boolean>;
  skillNewKeyName: Record<string, string>;
  skillNewKeyValue: Record<string, string>;
  onFilterChange: (next: string) => void;
  onRefresh: () => void;
  onToggle: (skillKey: string, enabled: boolean) => void;
  onEdit: (skillKey: string, value: string) => void;
  onSaveKey: (skillKey: string) => void;
  onInstall: (skillKey: string, name: string, installId: string) => void;
  onLinkVaultKey: (skillKey: string, vaultKeyId: string) => void;
  onToggleAddKey: (skillKey: string) => void;
  onNewKeyNameChange: (skillKey: string, name: string) => void;
  onNewKeyValueChange: (skillKey: string, value: string) => void;
  onAddKeyAndLink: (skillKey: string) => void;
};

export function renderSkills(props: SkillsProps) {
  const skills = props.report?.skills ?? [];
  const filter = props.filter.trim().toLowerCase();
  const filtered = filter
    ? skills.filter((skill) =>
        [skill.name, skill.description, skill.source].join(" ").toLowerCase().includes(filter),
      )
    : skills;
  const groups = groupSkills(filtered);

  return html`
    <section class="card">
      <div class="row" style="justify-content: space-between;">
        <div>
          <div class="card-title">Skills</div>
          <div class="card-sub">Bundled, managed, and workspace skills.</div>
        </div>
        <button class="btn" ?disabled=${props.loading} @click=${props.onRefresh}>
          ${props.loading ? "Loading…" : "Refresh"}
        </button>
      </div>

      <div class="filters" style="margin-top: 14px;">
        <label class="field" style="flex: 1;">
          <span>Filter</span>
          <input
            .value=${props.filter}
            @input=${(e: Event) => props.onFilterChange((e.target as HTMLInputElement).value)}
            placeholder="Search skills"
          />
        </label>
        <div class="muted">${filtered.length} shown</div>
      </div>

      ${
        props.error
          ? html`<div class="callout danger" style="margin-top: 12px;">${props.error}</div>`
          : nothing
      }

      ${
        filtered.length === 0
          ? html`
              <div class="muted" style="margin-top: 16px">No skills found.</div>
            `
          : html`
            <div class="agent-skills-groups" style="margin-top: 16px;">
              ${groups.map((group) => {
                const collapsedByDefault = false;
                return html`
                  <details class="agent-skills-group" ?open=${!collapsedByDefault}>
                    <summary class="agent-skills-header">
                      <span>${group.label}</span>
                      <span class="muted">${group.skills.length}</span>
                    </summary>
                    <div class="list skills-grid">
                      ${group.skills.map((skill) => renderSkill(skill, props))}
                    </div>
                  </details>
                `;
              })}
            </div>
          `
      }
    </section>
  `;
}

function renderSkill(skill: SkillStatusEntry, props: SkillsProps) {
  const busy = props.busyKey === skill.skillKey;
  const apiKey = props.edits[skill.skillKey] ?? "";
  const message = props.messages[skill.skillKey] ?? null;
  const canInstall = skill.install.length > 0 && skill.missing.bins.length > 0;
  const showBundledBadge = Boolean(skill.bundled && skill.source !== "openclaw-bundled");
  const missing = computeSkillMissing(skill);
  const reasons = computeSkillReasons(skill);
  return html`
    <div class="list-item">
      <div class="list-main">
        <div class="list-title">
          ${skill.emoji ? `${skill.emoji} ` : ""}${skill.name}
        </div>
        <div class="list-sub">${clampText(skill.description, 140)}</div>
        ${renderSkillStatusChips({ skill, showBundledBadge })}
        ${
          missing.length > 0
            ? html`
              <div class="muted" style="margin-top: 6px;">
                Missing: ${missing.join(", ")}
              </div>
            `
            : nothing
        }
        ${
          reasons.length > 0
            ? html`
              <div class="muted" style="margin-top: 6px;">
                Reason: ${reasons.join(", ")}
              </div>
            `
            : nothing
        }
      </div>
      <div class="list-meta">
        <div class="row" style="justify-content: flex-end; flex-wrap: wrap;">
          <button
            class="btn"
            ?disabled=${busy}
            @click=${() => props.onToggle(skill.skillKey, skill.disabled)}
          >
            ${skill.disabled ? "Enable" : "Disable"}
          </button>
          ${
            canInstall
              ? html`<button
                class="btn"
                ?disabled=${busy}
                @click=${() => props.onInstall(skill.skillKey, skill.name, skill.install[0].id)}
              >
                ${busy ? "Installing…" : skill.install[0].label}
              </button>`
              : nothing
          }
        </div>
        ${
          message
            ? html`<div
              class="muted"
              style="margin-top: 8px; color: ${
                message.kind === "error"
                  ? "var(--danger-color, #d14343)"
                  : "var(--success-color, #0a7f5a)"
              };"
            >
              ${message.message}
            </div>`
            : nothing
        }
        ${
          skill.primaryEnv
            ? renderVaultKeySelector(skill, props)
            : nothing
        }
      </div>
    </div>
  `;
}

function renderVaultKeySelector(skill: SkillStatusEntry, props: SkillsProps) {
  const busy = props.busyKey === skill.skillKey;
  const isLinked = Boolean(skill.vaultKeyId);
  const adding = props.skillAddingKey[skill.skillKey] ?? false;
  const newName = props.skillNewKeyName[skill.skillKey] ?? "";
  const newValue = props.skillNewKeyValue[skill.skillKey] ?? "";

  if (isLinked) {
    // Show current vault link
    return html`
      <div style="margin-top:10px;display:flex;align-items:center;gap:8px;">
        <span style="font-size:12px;color:var(--text-muted);">🔒</span>
        <span style="font-size:13px;font-family:monospace;color:var(--text);">${skill.vaultKeyId}</span>
        <button class="btn" style="font-size:11px;padding:2px 8px;" ?disabled=${busy}
          @click=${() => props.onLinkVaultKey(skill.skillKey, "")}
          title="Unlink vault key">Unlink</button>
      </div>
    `;
  }

  // Show dropdown selector
  return html`
    <div style="margin-top:10px;">
      <div style="display:flex;align-items:center;gap:8px;">
        <select
          style="flex:1;padding:5px 8px;background:var(--bg-surface,#0d1117);border:1px solid var(--border,#30363d);border-radius:6px;color:var(--text);font-size:13px;"
          ?disabled=${busy}
          @change=${(e: Event) => {
            const val = (e.target as HTMLSelectElement).value;
            if (val === "__add__") {
              props.onToggleAddKey(skill.skillKey);
              (e.target as HTMLSelectElement).value = "";
            } else if (val) {
              props.onLinkVaultKey(skill.skillKey, val);
            }
          }}
        >
          <option value="">Select vault key for ${skill.primaryEnv}…</option>
          ${props.vaultKeys.map((k) => html`
            <option value=${k.id}>🔒 ${k.id}</option>
          `)}
          <option disabled>──────────</option>
          <option value="__add__">＋ Add new vault key…</option>
        </select>
      </div>
      ${adding ? html`
        <div style="margin-top:8px;padding:10px;background:var(--bg-surface,#0d1117);border:1px solid var(--border,#30363d);border-radius:6px;">
          <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
            <input type="text" placeholder="KEY_NAME"
              style="width:160px;padding:5px 8px;background:var(--bg-surface,#0d1117);border:1px solid var(--border,#30363d);border-radius:4px;color:var(--text);font-size:12px;font-family:monospace;"
              .value=${newName}
              @input=${(e: Event) => props.onNewKeyNameChange(skill.skillKey, (e.target as HTMLInputElement).value)}
            />
            <input type="password" placeholder="Secret value"
              style="flex:1;min-width:120px;padding:5px 8px;background:var(--bg-surface,#0d1117);border:1px solid var(--border,#30363d);border-radius:4px;color:var(--text);font-size:12px;"
              .value=${newValue}
              @input=${(e: Event) => props.onNewKeyValueChange(skill.skillKey, (e.target as HTMLInputElement).value)}
            />
            <button class="btn primary" style="font-size:11px;padding:4px 10px;"
              ?disabled=${busy || !newName.trim() || !newValue.trim()}
              @click=${() => props.onAddKeyAndLink(skill.skillKey)}>Save & Link</button>
            <button class="btn" style="font-size:11px;padding:4px 10px;"
              @click=${() => props.onToggleAddKey(skill.skillKey)}>Cancel</button>
          </div>
        </div>
      ` : nothing}
    </div>
  `;
}
